ControlPropertyState.AutoRuleBindingString:
If(
    varFromUnknownList,
    With(
        {
            imageFileName: Last(
                Split(First(Split(Text(Coalesce(varImageUrl, "")), "?")).Value, "/")
            ).Value
        },
        Coalesce(
            LookUp(
                Documents,
                '{FilenameWithExtension}' = imageFileName
            ).'{Thumbnail}'.Large,
            LookUp(
                Documents,
                '{FilenameWithExtension}' = Text(varPackageId) & ".jpg"
            ).'{Thumbnail}'.Large,
            LookUp(
                Documents,
                '{FilenameWithExtension}' = imageFileName
            ).'{Thumbnail}'.Large,
            If(!IsBlank(varImage) && varImage <> SampleImage, varImage, Blank()),
            SampleImage
        )
    ),
    Coalesce(
        If(!IsBlank(varImage) && varImage <> SampleImage, varImage, Blank()),
        LookUp(colHomeQueue, id = Coalesce(varHomeQueueId, varHomeSelectedId)).image,
        If(
            Text(LookUp(colHomeQueue, id = Coalesce(varHomeQueueId, varHomeSelectedId)).source) <> "sharepoint",
            varImageUrl,
            Blank()
        ),
        SampleImage
    )
)
